import {api} from './api.js';import {payment} from './finance.js';
const app=document.querySelector('#app');const money=x=>Math.round(x).toLocaleString('ru-RU')+' ₽';let profile;let secured=false;let amount=1000000;let months=24;let catalog=[];let rendering=0;let selection={};
const scenario=()=>({...profile,...selection});
const labels={approved:'Предварительно одобрено',counteroffer:'Предлагаем другие условия',declined:'Не удалось одобрить',pending:'На рассмотрении'};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function showDialog(title,content){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=`<div class="row"><h2>${title}</h2><button class="secondary" id="close">Закрыть</button></div>${content}`;document.body.append(d);d.querySelector('#close').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());d.showModal();return d}
function result(item){const d=item.decision;const modal=showDialog(labels[d.status],`<span class="tag">Заявка № ${item.id}</span><h3>${escape(item.productName)}</h3><p>${escape(d.reason)}</p>${d.status!=='declined'?`<div class="metrics"><div>Сумма<strong>${money(d.amount)}</strong></div><div>Срок<strong>${d.months/12} г.</strong></div><div>Ставка<strong>${d.rate??'—'}%</strong></div></div>`:''}<p>Запрошено: ${money(item.requested.amount)} на ${item.requested.months/12} г.</p>${item.scoringMonthlyPayment!=null?`<p>Платёж по расчёту сервера: ${money(item.scoringMonthlyPayment)}</p>`:''}${d.status==='counteroffer'?'<div class="actions"><button data-answer="true">Принять условия</button><button class="secondary" data-answer="false">Отклонить</button></div>':''}${d.status==='pending'?'<button id="refresh-result" class="secondary">Обновить статус</button>':''}<p class="fine">Одобрение заявки не означает подписание договора или выдачу средств.</p><p role="alert" id="result-error"></p><a class="button" href="#/applications" id="to-applications">Мои заявки</a>`);modal.querySelector('#to-applications').onclick=()=>modal.close();modal.querySelectorAll('[data-answer]').forEach(b=>b.onclick=async()=>{modal.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);try{result(await api.respond(item.id,b.dataset.answer==='true'))}catch(e){modal.querySelector('#result-error').textContent=e.message;modal.querySelectorAll('[data-answer]').forEach(x=>x.disabled=false)}});const refresh=modal.querySelector('#refresh-result');if(refresh)refresh.onclick=async()=>{refresh.disabled=true;try{result(await api.getApplication(item.id))}catch(e){modal.querySelector('#result-error').textContent=e.message;refresh.disabled=false}}}
function authForm(register=false){const modal=showDialog(register?'Регистрация':'Войти в аккаунт',`<form id="auth-form" class="auth-form"><label>Логин<input name="login" autocomplete="username" required maxlength="100"></label><label>Пароль<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" required></label>${register?'<label>Имя<input name="firstName" required></label><label>Фамилия<input name="lastName" required></label><label>Отчество<input name="secondName"></label><label>Тип организации<select name="organizationType"><option value="OOO">ООО</option><option value="IP">ИП</option><option value="AO">АО</option></select></label><label>ИНН<input name="inn" pattern="[0-9]{10}|[0-9]{12}" required></label><label>ОГРН / ОГРНИП<input name="ogrn" pattern="[0-9]{13}|[0-9]{15}" required></label><label>Дата регистрации<input name="registrationDate" type="date" required></label><label>ОКВЭД<input name="okved" required></label>':''}<p role="alert" id="auth-error"></p><button type="submit">${register?'Зарегистрироваться':'Войти'}</button><button type="button" class="secondary" id="switch-auth">${register?'Уже есть аккаунт':'Создать аккаунт'}</button></form>`);modal.querySelector('#switch-auth').onclick=()=>authForm(!register);modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;const data=Object.fromEntries(new FormData(e.target));try{register?await api.register(data):await api.login(data.login,data.password);modal.close();await render()}catch(err){modal.querySelector('#auth-error').textContent=err.message;b.disabled=false}}}
async function renderCards(){const target=document.querySelector('#products');if(!target)return;try{catalog=await api.getProducts();target.innerHTML=catalog.length?catalog.map(p=>{const valid=amount>=p.min&&amount<=p.max&&months>=p.minMonths&&months<=p.maxMonths;const monthly=payment(amount,months,p.rate);return `<article class="product"><img class="product-icon" src="assets/business.svg" alt=""><h2>${escape(p.name)}</h2><p>${escape(p.description)}</p><div class="metrics"><div>Ставка<strong>${p.rate}%</strong></div>${p.kind==='annuity'?`<div>Переплата<strong>${money(monthly*months-amount)}</strong></div><div>Платёж в месяц<strong>${money(monthly)}</strong></div>`:'<div>Погашение<strong>По графику</strong></div>'}</div><p class="fine">${money(p.min)} – ${money(p.max)} · ${p.minMonths/12}–${p.maxMonths/12} лет</p>${!valid?'<p class="validation">Измените сумму или срок согласно лимитам продукта.</p>':''}<div class="actions"><button class="secondary" data-details="${p.id}">Узнать подробнее</button><button data-apply="${p.id}" ${valid?'':'disabled'}>${api.isAuthenticated()?'Подать заявку':'Войти и подать заявку'}</button></div></article>`}).join(''):'<p>В каталоге пока нет продуктов.</p>';target.querySelectorAll('[data-details]').forEach(b=>b.onclick=()=>{const p=catalog.find(x=>String(x.id)===b.dataset.details);showDialog(escape(p.name),`<p>${escape(p.mainDifference)}</p><p>${escape(p.discountConditions||'Условия скидки не указаны')}</p><p>Ставка со скидкой: ${p.discountInterest}% — только при выполнении условий банка.</p>`)});target.querySelectorAll('[data-apply]').forEach(b=>b.onclick=async()=>{if(!api.isAuthenticated()){authForm();return}const product=catalog.find(x=>String(x.id)===b.dataset.apply);const modal=showDialog('Проверьте заявку',`<p>${escape(product.name)} · ${money(amount)} · ${months/12} г.</p><form id="submit-form" class="auth-form"><label>Цель финансирования<textarea name="purpose" maxlength="500" required></textarea></label><label><input type="checkbox" name="collateral" ${secured?'checked':''}> Предоставлю залог</label><p role="alert"></p><button>Отправить заявку</button></form>`);modal.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{result(await api.submitApplication({productId:product.id,amount,months,collateral:e.target.elements.collateral.checked,purpose:e.target.elements.purpose.value}))}catch(err){modal.querySelector('[role=alert]').textContent=err.message;button.disabled=false;if(err.status===401){modal.close();authForm()}}}})}catch(e){target.innerHTML='<p role="alert"></p><button class="secondary" id="retry-products">Повторить загрузку</button>';target.querySelector('p').textContent=e.message;target.querySelector('button').onclick=renderCards}}
async function render(){const run=++rendering;document.querySelector('dialog')?.close();document.querySelector('.profile-menu').classList.remove('open');document.querySelector('#profile-toggle').setAttribute('aria-expanded','false');app.innerHTML='<p role="status">Загружаем данные компании…</p>';try{profile=await api.getProfile();if(run!==rendering)return;updateMenu();if(!profile)profile={name:'Подберите финансирование для бизнеса',inn:'—',ageMonths:0,legalForm:'ООО',collateralAvailable:true};const route=location.hash.slice(2);if(route==='applications'&&!api.isAuthenticated()){app.innerHTML='<h1>Мои заявки</h1><p>Войдите, чтобы увидеть историю обращений.</p><button id=login-page>Войти</button>';document.querySelector('#login-page').onclick=()=>authForm();return}if(route==='applications'){const items=await api.listApplications();if(run!==rendering)return;app.innerHTML=`<div class="page-heading"><div><h1>Мои заявки</h1><p>История обращений и результаты рассмотрения</p></div><a class="button secondary" href="#/">Подать заявку</a></div><div class="application-list">${items.length?items.map(i=>`<article class="product"><span class="tag">${labels[i.decision.status]}</span><h2>${escape(i.productName)}</h2><p>${money(i.requested.amount)} · ${i.requested.months} мес. · ${new Date(i.createdAt).toLocaleDateString('ru-RU')}</p><button class="secondary" data-id="${i.id}">Посмотреть результат</button></article>`).join(''):'<article class="product"><h2>Заявок пока нет</h2><p>Выберите доступный продукт в калькуляторе и отправьте заявку.</p></article>'}</div>`;app.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>result(items.find(i=>String(i.id)===b.dataset.id)))}else if(route==='support'){app.innerHTML=`<h1>Поддержка</h1><div class="product"><h2>Поможем разобраться</h2><details open><summary>Как подбираются кредиты?</summary><p>Каталог загружается с сервера. Сравните суммы и сроки; окончательная проверка выполняется при отправке заявки.</p></details><details><summary>Почему предложена другая сумма?</summary><p>Сервис рассмотрения оценивает финансовые показатели. Предложенные параметры и комментарий доступны в результате заявки.</p></details><p class="fine">Канал связи с сотрудником пока не подключён.</p><a class="button secondary" href="#/">Подать заявку</a></div>`}else{app.innerHTML=`<section class="hero"><div><div class="eyebrow">Финансирование для бизнеса</div><h1>Ваш бизнес.<br>Ваши планы.<br><em>Наше решение.</em></h1><p>Закупить товары, обновить оборудование или открыть новое направление. Подберите финансирование под задачу вашего бизнеса — от первого расчёта до результата заявки.</p><button id="go-calculate">Подобрать кредит <img src="assets/arrow.svg" alt=""></button></div><div class="hero-visual"><img src="assets/business-growth.png" alt="Объёмная иллюстрация магазина с красной маркизой и ступеней роста"><div class="visual-caption"><img src="assets/chart.svg" alt=""><span>Для тех, кто строит<br><strong>большие планы</strong></span></div></div></section><section class="credit-calculator" id="calculator"><div class="company-bar"><div><strong>${escape(profile.name)}</strong><span>ИНН ${escape(profile.inn)} · Возраст бизнеса: ${profile.ageMonths} мес.</span></div><span class="tag">Данные аккаунта</span></div><h2 class="calculator-title" tabindex="-1">Рассчитаем кредит под вашу задачу</h2><div class="calc-layout"><aside class="filters"><div class="filter-group"><label>Ваша компания</label><p>${api.isAuthenticated()?escape(profile.legalForm)+' · ИНН '+escape(profile.inn):'Войдите при отправке заявки'}</p><small>Тип организации берётся из аккаунта. Доступность и условия проверяет сервер.</small></div><div class="range-box"><label for="amount">Сумма кредита</label><output id="amount-value">${money(amount)}</output><input id="amount" type="range" min="50000" max="30000000" step="50000" value="${amount}"><div class="ends"><span>50 тыс. ₽</span><span>15 млн ₽</span><span>30 млн ₽</span></div></div><div class="range-box"><label for="months">Срок кредита</label><output id="months-value">${months/12} г.</output><input id="months" type="range" min="12" max="360" step="12" value="${months}"><div class="ends"><span>1 год</span><span>15 лет</span><span>30 лет</span></div></div></aside><div id="products" class="products" aria-live="polite"></div></div></section><p class="disclaimer">Предварительный аннуитетный расчёт без комиссий и страхования. Ставки из каталога банка, итоговые условия — по результату рассмотрения.</p><div class="section-heading"><div class="eyebrow">От планов к возможностям</div><h2>Финансирование, которое подходит вам</h2><p>Сравните условия и оцените платёж. Укажите сумму и срок, затем выберите продукт из каталога.</p></div><section class="use-cases"><div class="section-heading"><div class="eyebrow">Каждому делу — свои возможности</div><h2>На что направить финансирование</h2><p>От ежедневных задач до следующего этапа развития. Начните с того, что сейчас важно вашему бизнесу.</p></div><div class="purpose-grid"><article><img src="assets/business.svg" alt=""><h3>Пополнить оборот</h3><p>Закупить товары, оплатить поставки и подготовиться к сезону, сохранив средства на текущие расходы.</p><span>Оборотный кредит</span></article><article><img src="assets/chart.svg" alt=""><h3>Вырастить бизнес</h3><p>Обновить оборудование, расширить пространство или вложиться в новое направление.</p><span>Инвестиции и развитие</span></article><article><img src="assets/document.svg" alt=""><h3>Закрыть кассовый разрыв</h3><p>Выполнить обязательства, пока ожидаете оплату от клиентов. Оцените краткосрочное финансирование.</p><span>Овердрафт</span></article></div></section><section class="transparency"><div class="transparency-heading"><img src="assets/shield.svg" alt=""><div class="eyebrow">Понятный процесс</div><h2>Не просто ответ.<br>Следующий шаг.</h2><p>После рассмотрения вы увидите результат и параметры предложения в одном месте.</p></div><div class="decision-explainer"><article><h3>Запрошенные условия подходят</h3><p>В результате появятся сумма и срок финансирования. Предварительное одобрение ещё не означает выдачу средств.</p></article><article><h3>Есть другой вариант</h3><p>При высокой нагрузке возможно предложение меньшей суммы или другого срока. Сравните его со своими планами.</p></article><article><h3>Финансирование недоступно</h3><p>Посмотрите причину в результате рассмотрения. История обращения останется в разделе «Мои заявки».</p></article></div></section><section class="how-it-works"><div class="section-heading"><h2>Три шага к вашим планам</h2></div><div class="steps"><article><span>01 / ПОДБОР</span><h3>Начните с задачи бизнеса</h3><p>Укажите параметры и сравните предложения. Калькулятор поможет оценить будущие расходы.</p></article><article><span>02 / ЗАЯВКА</span><h3>Выберите подходящий кредит</h3><p>Отправьте выбранные условия на рассмотрение. Сведения о компании уже есть в профиле.</p></article><article><span>03 / РЕЗУЛЬТАТ</span><h3>Держите всё под контролем</h3><p>Посмотрите решение и предложенные условия. История обращений доступна в «Моих заявках».</p></article></div></section><section class="home-faq"><div class="section-heading"><div class="eyebrow">Полезно знать</div><h2>Вопросы перед первым шагом</h2></div><details><summary>Как выбираются доступные продукты?</summary><p>В калькуляторе показаны продукты из каталога банка. Сумма и срок должны соответствовать ограничениям выбранного продукта. Окончательную доступность проверяет банк.</p></details><details><summary>Что влияет на результат рассмотрения?</summary><p>Финансовые показатели бизнеса, действующие обязательства и параметры заявки. Математическая модель оценивает показатели, а кредитные правила определяют результат. Результат поступает от сервиса принятия решений.</p></details><details><summary>Ставка в калькуляторе окончательная?</summary><p>Нет. Ставки загружаются из каталога продуктов. Расчёт не учитывает комиссии и страхование; реальные условия должны поступать от банка.</p></details><details><summary>Где найти отправленную заявку?</summary><p>Откройте значок профиля справа вверху и выберите «Мои заявки». История загружается из вашего аккаунта на сервере.</p></details></section>`;document.querySelector('#go-calculate').onclick=()=>{document.querySelector('#calculator').scrollIntoView({behavior:'smooth'});document.querySelector('.calculator-title').focus({preventScroll:true})};const updateFilters=()=>{app.querySelectorAll('[data-form]').forEach(b=>{const on=b.dataset.form===scenario().legalForm;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});app.querySelectorAll('[data-age]').forEach(b=>{const on=(+b.dataset.age>=9)===(scenario().ageMonths>=9);b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});app.querySelectorAll('[data-secured]').forEach(b=>{const on=(b.dataset.secured==='true')===secured;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))});renderCards()};app.querySelectorAll('[data-form]').forEach(b=>b.onclick=()=>{selection.legalForm=b.dataset.form;updateFilters()});app.querySelectorAll('[data-age]').forEach(b=>b.onclick=()=>{selection.ageMonths=+b.dataset.age;updateFilters()});app.querySelectorAll('[data-secured]').forEach(b=>b.onclick=()=>{secured=b.dataset.secured==='true';updateFilters()});for(const id of ['amount','months'])document.getElementById(id).oninput=e=>{if(id==='amount')amount=+e.target.value;else months=+e.target.value;document.getElementById(id+'-value').textContent=id==='amount'?money(amount):months/12+' г.';renderCards()};await renderCards()}}catch(e){app.innerHTML='<h1>Не удалось загрузить данные</h1><p role=alert></p><button id=retry-page>Повторить</button>';app.querySelector('p').textContent=e.message;app.querySelector('button').onclick=()=>e.status===401?authForm():render()}}
function updateMenu(){const nav=document.querySelector('.dropdown');nav.innerHTML=api.isAuthenticated()?'<a href="#/applications">Мои заявки</a><a href="#/support">Поддержка</a><button id=logout-button class=secondary>Выйти</button>':'<button id=login-button>Войти</button><a href="#/support">Поддержка</a>';nav.querySelector('#login-button')?.addEventListener('click',()=>authForm());nav.querySelector('#logout-button')?.addEventListener('click',async()=>{try{await api.logout()}catch{}location.hash='/';render()})}
const menu=document.querySelector('.profile-menu');const toggle=document.querySelector('#profile-toggle');toggle.onclick=()=>{const open=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))};document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.classList.remove('open');toggle.setAttribute('aria-expanded','false')}});document.addEventListener('click',e=>{if(!menu.contains(e.target)){menu.classList.remove('open');toggle.setAttribute('aria-expanded','false')}});window.addEventListener('hashchange',render);render();
